use crate::aap::caps::state_read;

struct Node;

/// Keys the subscription list may be stored under, tried in order.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds", "list"];

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => cur.push('"'),
                            '\\' => cur.push('\\'),
                            '/' => cur.push('/'),
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            _ => return None,
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            _ => return None,
        }
    }
    // Nothing but whitespace may follow the closing bracket.
    if chars.any(|c| !c.is_whitespace()) {
        return None;
    }
    Some(out)
}

/// Parse a newline- or comma-separated list, ignoring blanks and `#` comments.
fn parse_lines(s: &str) -> Vec<String> {
    s.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .flat_map(|l| l.split(','))
        .map(|u| u.trim().to_string())
        .filter(|u| !u.is_empty())
        .collect()
}

fn parse(value: &str) -> Vec<String> {
    let raw = parse_json_string_array(value).unwrap_or_else(|| parse_lines(value));
    let mut urls: Vec<String> = Vec::with_capacity(raw.len());
    for u in raw {
        let u = u.trim().to_string();
        if !u.is_empty() && !urls.contains(&u) {
            urls.push(u);
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(value) = state_read::get(key) {
                let urls = parse(&value);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // No usable subscriptions: fail the run rather than emit an output
        // that violates `ensures present(urls)`.
        panic!("LoadSubscriptions: no subscriptions found in state store");
    }
}

export!(Node);
```

